/// How the API key is sent in the HTTP request.
#[frb(mirror(AuthHeaderFormat), unignore)]
pub enum AuthHeaderFormat {
    /// Bearer token: `Authorization: Bearer <key>`
    Bearer,
    /// Custom header: e.g., `X-Api-Key: <key>`
    ApiKey { field0: String },
    /// No authentication required.
    None,
}

/// The streaming wire format a provider uses for its response stream.
///
/// Most providers use standard Server-Sent Events (SSE).  AWS Bedrock uses
/// a proprietary binary EventStream framing.
///
/// Deserialized from the `streaming_format` JSON field via [`serde`].
#[frb(mirror(StreamFormat), unignore)]
pub enum StreamFormat {
    /// Standard Server-Sent Events (text/event-stream).
    Sse,
    /// AWS EventStream binary framing (application/vnd.amazon.eventstream).
    AwsEventStream,
}

/// Auth scheme used by a provider.
#[frb(mirror(AuthType), unignore)]
pub enum AuthType {
    /// Standard `Authorization: Bearer <key>` header.
    Bearer,
    /// `x-api-key: <key>` header (also handles `"header"` and `"x-api-key"` aliases).
    ApiKey,
    /// No authentication header required.
    None,
    /// Unrecognised auth scheme — falls back to bearer.
    Unknown,
}

/// Result of a [`refresh_catalog`] call.
#[frb(mirror(RefreshOutcome), unignore)]
pub enum RefreshOutcome {
    /// `config.enabled` was `false`; no network, filesystem, or overlay
    /// activity occurred.
    Disabled,
    /// The on-disk cache was fresh (age < `ttl_seconds`); the overlay was
    /// installed from the cached file without a network request.
    FromCache,
    /// The catalog was fetched over the network, the cache file was
    /// (best-effort) refreshed, and the overlay was installed from the
    /// fetched catalog.
    Fetched,
}

/// How budget limits are enforced.
#[frb(mirror(Enforcement), unignore)]
pub enum Enforcement {
    /// Reject requests that would exceed the budget with
    /// [`LiterLlmError::BudgetExceeded`].
    Hard,
    /// Allow requests through but emit a `tracing::warn!` when the budget is
    /// exceeded.
    Soft,
}

/// Storage backend for the response cache.
#[frb(mirror(CacheBackend), unignore)]
pub enum CacheBackend {
    /// In-memory LRU cache (default). No external dependencies.
    Memory,
    /// OpenDAL-backed storage. Supports 40+ backends (S3, Redis, GCS, local FS, etc.).
    OpenDal {
        /// OpenDAL scheme name (e.g. "s3", "redis", "fs", "gcs", "azblob").
        scheme: String,
        /// Backend-specific configuration as key-value pairs passed to OpenDAL.
        config: std::collections::HashMap<String, String>,
    },
}

/// Observable state of a circuit breaker.
#[frb(mirror(CircuitState), unignore)]
pub enum CircuitState {
    /// Requests flow through normally.
    Closed,
    /// All requests are rejected; the circuit is waiting for the backoff to elapse.
    Open,
    /// One probe request is allowed through to test service health.
    HalfOpen,
}

/// The result of a single health probe.
#[frb(mirror(HealthStatus), unignore)]
pub enum HealthStatus {
    /// The probe succeeded; the upstream is reachable.
    Healthy,
    /// The probe failed; the upstream may be down.
    Unhealthy,
}

/// All errors that can occur when using `liter-llm`.
///
/// Each variant carries a stable numeric `error_code` (>= 100) that bindings expose
/// across the FFI boundary. Codes are append-only: never renumber or reuse a code.
#[frb(mirror(LiterLlmError), unignore)]
pub enum LiterLlmError {
    /// `status` preserves the exact HTTP status code received (401 or 403).
    Authentication {
        message: String,
        status: i64,
    },
    RateLimited {
        message: String,
        retry_after: i64,
    },
    /// `status` preserves the exact HTTP status code received (400, 405, 413, 422, …).
    BadRequest {
        message: String,
        status: i64,
    },
    ContextWindowExceeded {
        message: String,
    },
    ContentPolicy {
        message: String,
    },
    NotFound {
        message: String,
    },
    /// `status` preserves the exact HTTP status code received (500, or other 5xx not covered
    /// by `ServiceUnavailable`).
    ServerError {
        message: String,
        status: i64,
    },
    /// `status` preserves the exact HTTP status code received (502, 503, or 504).
    ServiceUnavailable {
        message: String,
        status: i64,
        retry_after: i64,
    },
    Timeout,
    Network {
        message: String,
    },
    /// A catch-all for errors that occur during streaming response processing.
    ///
    /// This variant covers multiple sub-conditions including UTF-8 decoding
    /// failures, CRC/checksum mismatches (AWS EventStream), JSON parse errors
    /// in individual SSE chunks, and buffer overflow conditions.  The `message`
    /// field contains a human-readable description of the specific failure.
    Streaming {
        message: String,
    },
    EndpointNotSupported {
        endpoint: String,
        provider: String,
    },
    InvalidHeader {
        name: String,
        reason: String,
    },
    Serialization {
        field0: String,
    },
    BudgetExceeded {
        message: String,
        model: String,
    },
    HookRejected {
        message: String,
    },
    /// An internal logic error (e.g. unexpected Tower response variant).
    ///
    /// This should never surface in normal operation — if it does, it
    /// indicates a bug in the library.
    InternalError {
        message: String,
    },
    /// An outbound request was blocked by the active `OutboundPolicy`.
    ///
    /// Returned when `register_custom_provider` is called with a `base_url` that
    /// violates the policy (e.g. a private-range IP under `DenyPrivate`), or when
    /// the per-connection DNS resolver detects a forbidden address at connect time.
    OutboundForbidden {
        url: String,
        reason: String,
    },
    /// A different request body was submitted for an existing `Idempotency-Key`.
    ///
    /// Per the OpenAI `Idempotency-Key` convention, once a key is used with a
    /// particular request body, subsequent requests using the same key must carry
    /// an identical body.  A body mismatch is a hard error (not retryable).
    ///
    /// HTTP equivalent: 409 Conflict.
    IdempotencyConflict {
        key: String,
    },
    /// The same `Idempotency-Key` is already in-flight (another request with the
    /// same key is currently being processed).
    ///
    /// The caller should wait briefly and retry.  The response is not yet
    /// available, and this request has been short-circuited to avoid running
    /// the operation twice.
    ///
    /// HTTP equivalent: 409 Conflict (retryable after a brief delay).
    IdempotencyInFlight {
        key: String,
    },
    /// The upstream provider rejected the request because the account quota is exhausted.
    ProviderQuotaExceeded {
        message: String,
        status: i64,
    },
}

#[allow(unreachable_patterns)]
impl From<&LiterLlmError> for liter_llm::LiterLlmError {
    fn from(m: &LiterLlmError) -> Self {
        match m {
            LiterLlmError::Authentication {
                message: f_message,
                status: f_status,
            } => Self::Authentication {
                message: f_message.clone(),
                status: *f_status as u16,
            },
            LiterLlmError::RateLimited {
                message: f_message,
                retry_after: f_retry_after,
            } => Self::RateLimited {
                message: f_message.clone(),
                retry_after: Some(std::time::Duration::from_millis(*f_retry_after as u64)),
            },
            LiterLlmError::BadRequest {
                message: f_message,
                status: f_status,
            } => Self::BadRequest {
                message: f_message.clone(),
                status: *f_status as u16,
            },
            LiterLlmError::ContextWindowExceeded { message: f_message } => Self::ContextWindowExceeded {
                message: f_message.clone(),
            },
            LiterLlmError::ContentPolicy { message: f_message } => Self::ContentPolicy {
                message: f_message.clone(),
            },
            LiterLlmError::NotFound { message: f_message } => Self::NotFound {
                message: f_message.clone(),
            },
            LiterLlmError::ServerError {
                message: f_message,
                status: f_status,
            } => Self::ServerError {
                message: f_message.clone(),
                status: *f_status as u16,
            },
            LiterLlmError::ServiceUnavailable {
                message: f_message,
                status: f_status,
                retry_after: f_retry_after,
            } => Self::ServiceUnavailable {
                message: f_message.clone(),
                status: *f_status as u16,
                retry_after: Some(std::time::Duration::from_millis(*f_retry_after as u64)),
            },
            LiterLlmError::Timeout => Self::Timeout,
            LiterLlmError::Network { message: f_message } => Self::Network {
                message: f_message.clone(),
            },
            LiterLlmError::Streaming { message: f_message } => Self::Streaming {
                message: f_message.clone(),
            },
            LiterLlmError::EndpointNotSupported {
                endpoint: f_endpoint,
                provider: f_provider,
            } => Self::EndpointNotSupported {
                endpoint: f_endpoint.clone(),
                provider: f_provider.clone(),
            },
            LiterLlmError::InvalidHeader {
                name: f_name,
                reason: f_reason,
            } => Self::InvalidHeader {
                name: f_name.clone(),
                reason: f_reason.clone(),
            },
            LiterLlmError::Serialization { .. } => {
                unreachable!("variant with binding-excluded fields cannot be constructed on dart side")
            }
            LiterLlmError::BudgetExceeded {
                message: f_message,
                model: f_model,
            } => Self::BudgetExceeded {
                message: f_message.clone(),
                model: Some(f_model.clone()),
            },
            LiterLlmError::HookRejected { message: f_message } => Self::HookRejected {
                message: f_message.clone(),
            },
            LiterLlmError::InternalError { message: f_message } => Self::InternalError {
                message: f_message.clone(),
            },
            LiterLlmError::OutboundForbidden {
                url: f_url,
                reason: f_reason,
            } => Self::OutboundForbidden {
                url: f_url.clone(),
                reason: f_reason.clone(),
            },
            LiterLlmError::IdempotencyConflict { key: f_key } => Self::IdempotencyConflict { key: f_key.clone() },
            LiterLlmError::IdempotencyInFlight { key: f_key } => Self::IdempotencyInFlight { key: f_key.clone() },
            LiterLlmError::ProviderQuotaExceeded {
                message: f_message,
                status: f_status,
            } => Self::ProviderQuotaExceeded {
                message: f_message.clone(),
                status: *f_status as u16,
            },
        }
    }
}

impl LiterLlmError {
    /// Returns the canonical HTTP status code associated with this error.
    ///
    /// Maps error variants to their originating HTTP status code as set by
    /// the private `from_status` constructor. Used by e2e assertions that check
    /// `error.status_code` against the expected HTTP status.
    #[frb]
    pub fn status_code(&self) -> i64 {
        let real: liter_llm::LiterLlmError = self.into();
        real.status_code() as i64
    }
    /// Returns the server-advertised retry delay, when the error carries one.
    ///
    /// Parsed from the upstream `Retry-After` header on a 429.  Exposed as an
    /// accessor alongside [`Self::status_code`] and [`Self::error_type`] so the
    /// generated bindings can surface it: the value reached the Rust core but
    /// stopped there, leaving every binding consumer to re-derive its own
    /// backoff from nothing more than the status code.
    #[frb]
    pub fn retry_after(&self) -> Option<i64> {
        let real: liter_llm::LiterLlmError = self.into();
        real.retry_after().map(|d| d.as_millis() as i64)
    }
    /// Returns `true` for errors that are worth retrying on a different service
    /// or deployment (transient failures).
    ///
    /// Used by `FallbackService` and
    /// `Router` to decide whether to route to an
    /// alternative endpoint.
    #[frb]
    pub fn is_transient(&self) -> bool {
        let real: liter_llm::LiterLlmError = self.into();
        real.is_transient()
    }
    /// Return the OpenTelemetry `error.type` string for this error variant.
    ///
    /// Used by the tracing middleware to record the `error.type` span attribute
    /// on failed requests per the GenAI semantic conventions.
    #[frb]
    pub fn error_type(&self) -> String {
        let real: liter_llm::LiterLlmError = self.into();
        real.error_type().to_string()
    }
}

/// Errors from [`refresh_catalog`] and [`install_catalog_overlay_from_str`].
///
/// On every variant, the overlay registry is left untouched: a previously
/// installed overlay (or the embedded catalog, if none was ever installed)
/// remains active. This is the air-gap-safety contract — a failed refresh
/// never degrades pricing/model-info availability.
#[frb(mirror(CatalogRefreshError), unignore)]
pub enum CatalogRefreshError {
    /// Runtime catalog refresh was not enabled. [`refresh_catalog`] itself
    /// never returns this — it returns `Ok(`[`RefreshOutcome::Disabled`]`)`
    /// instead — but the variant is part of the public error surface for
    /// callers that want to treat "disabled" as a hard error.
    Disabled,
    /// `source_url` did not use the `https` scheme, or failed to parse as a
    /// URL at all. There is no host allowlist: the URL is user-configurable
    /// for self-hosted catalog mirrors, so only the scheme is enforced.
    InsecureUrl { url: String },
    /// The network fetch failed, timed out, or returned a non-success
    /// status.
    Fetch { url: String, message: String },
    /// The fetched or cached catalog JSON failed to parse.
    Parse { message: String },
    /// A cache file **read** failed on an otherwise-fresh cache file. Cache
    /// **write** failures are best-effort and never surface as this error
    /// (see [`refresh_catalog`]).
    Cache { path: String, message: String },
    /// Catalog bytes did not match the published SHA-256 checksum.
    Integrity { message: String },
}

