/// Create a client from binding-friendly options.
///
/// **Errors:**
///
/// Returns `LiterLlmError.BadRequest` for a zero or platform-overflowing
/// `max_response_bytes`, plus the errors documented by `create_client`.
#[cfg(feature = "native-http")]
pub fn create_client_with_options(options: ClientOptions) -> Result<DefaultClient, String> {
    let item = &options;
    if let Some(value) = item.timeout_secs {
        u64::try_from(value).map_err(|_| "ClientOptions.timeout_secs is outside the valid u64 range".to_string())?;
    }
    if let Some(value) = item.max_retries {
        u32::try_from(value).map_err(|_| "ClientOptions.max_retries is outside the valid u32 range".to_string())?;
    }
    if let Some(value) = item.max_response_bytes {
        u64::try_from(value)
            .map_err(|_| "ClientOptions.max_response_bytes is outside the valid u64 range".to_string())?;
    }
    liter_llm::create_client_with_options(liter_llm::ClientOptions::from(options))
        .map(|inner| DefaultClient { inner })
        .map_err(|e| e.to_string())
}

/// Create a new LLM client with simple scalar configuration.
///
/// This is the primary binding entry-point. All parameters except `api_key`
/// are optional — omitting them uses the same defaults as
/// `ClientConfigBuilder`.
///
/// **Errors:**
///
/// Returns `LiterLlmError` if the underlying HTTP client cannot be
/// constructed, or if the resolved provider configuration is invalid.
#[cfg(any(feature = "native-http", feature = "wasm-http"))]
pub fn create_client(
    api_key: String,
    base_url: Option<String>,
    timeout_secs: Option<i64>,
    max_retries: Option<i64>,
    model_hint: Option<String>,
) -> Result<DefaultClient, String> {
    liter_llm::create_client(
        api_key,
        base_url,
        timeout_secs
            .map(|v| {
                u64::try_from(v).map_err(|_| "parameter 'timeout_secs' must be between 0 and u64::MAX".to_string())
            })
            .transpose()?,
        max_retries
            .map(|v| u32::try_from(v).map_err(|_| "parameter 'max_retries' must be between 0 and u32::MAX".to_string()))
            .transpose()?,
        model_hint,
    )
    .map(|inner| DefaultClient { inner })
    .map_err(|e| e.to_string())
}

/// Create a new LLM client from a JSON string.
///
/// The JSON object accepts the same fields as `liter-llm.toml` (snake_case).
/// Middleware keys (`cache`, `budget`, `cooldown_secs`, `rate_limit`,
/// `in_flight_limit`, `health_check_secs`, `cost_tracking`, `tracing`) are
/// applied: the returned client routes the `LlmClient` methods (`chat`,
/// `chat_stream`, `embed`, `list_models`, `image_generate`, `speech`,
/// `transcribe`, `moderate`, `rerank`, `search`, `ocr`) through the managed
/// Tower stack. File, batch and response operations bypass it. Each `providers`
/// entry is registered process-wide via `register_custom_provider`.
///
/// **Errors:**
///
/// Returns `LiterLlmError.BadRequest` if `json` is not valid JSON, contains
/// unknown fields, or sets middleware keys in a build without the `tower` and
/// `native-http` features. Provider registration failures are propagated.
#[cfg(any(feature = "native-http", feature = "wasm-http"))]
pub fn create_client_from_json(json: String) -> Result<DefaultClient, String> {
    liter_llm::create_client_from_json(&json)
        .map(|inner| DefaultClient { inner })
        .map_err(|e| e.to_string())
}

/// Encode bytes as a base64 data URL: `data:<mime>;base64,<b64>`.
///
/// `mime` defaults to `IMAGE_PNG` when `null`.
pub fn encode_data_url(bytes: Vec<u8>, mime: Option<String>) -> String {
    liter_llm::image::encode_data_url(&bytes, mime.as_deref()).to_string()
}

/// Decode a base64 data URL into `DecodedDataUrl`.
///
/// Returns `null` for:
///
/// - Non-data URLs (strings that do not start with `"data:"`).
/// - Malformed prefixes (missing `";base64,"` marker).
/// - Invalid base64 payloads.
///
/// The returned MIME string is extracted verbatim from the URL prefix —
/// it is not validated or normalised.
pub fn decode_data_url(url: String) -> Option<DecodedDataUrl> {
    liter_llm::image::decode_data_url(&url).map(DecodedDataUrl::from)
}

/// Register a custom provider in the global runtime registry.
///
/// The provider will be checked **before** all built-in providers during model
/// detection. If a provider with the same `name` already exists it is replaced.
///
/// **Errors:**
///
/// Returns an error if the config is invalid (empty name, empty base_url, or
/// no model prefixes).
pub fn register_custom_provider(config: CustomProviderConfig) -> Result<(), String> {
    liter_llm::provider::custom::register_custom_provider(unsafe {
        std::mem::transmute::<CustomProviderConfig, liter_llm::provider::custom::CustomProviderConfig>(config)
    })
    .map(|v| v)
    .map_err(|e| e.to_string())
}

/// Remove a previously registered custom provider by name.
///
/// Returns `true` if a provider with the given name was found and removed,
/// `false` if no such provider existed.
///
/// **Errors:**
///
/// Returns an error if the custom-provider registry cannot be updated.
pub fn unregister_custom_provider(name: String) -> Result<bool, String> {
    liter_llm::provider::custom::unregister_custom_provider(&name)
        .map(|v| v)
        .map_err(|e| e.to_string())
}

/// Return the capability flags for a named provider.
///
/// Performs an O(n) linear scan over the embedded registry (174 entries).
/// Returns an owned value so bindings can pass capability data without
/// borrowing registry internals.
///
/// For unknown `provider_name` values the function returns an all-`false`
/// sentinel so callers never need to handle `Option`.
pub fn capabilities(provider_name: String) -> ProviderCapabilities {
    ProviderCapabilities::from(liter_llm::provider::capabilities(&provider_name))
}

/// Return all provider configs from the registry.
///
/// Useful for tooling, documentation generation, or runtime enumeration.
/// Returns the public `ProviderConfig` slice (without capability flags).
/// To query capability flags for a specific provider use `capabilities`.
pub fn all_providers() -> Result<Vec<ProviderConfig>, String> {
    liter_llm::provider::all_providers()
        .map(|v| v.iter().map(|x| ProviderConfig::from(x.clone())).collect::<Vec<_>>())
        .map_err(|e| e.to_string())
}

/// Return the set of complex provider names.
///
/// Complex providers require custom auth/routing logic beyond simple bearer
/// tokens (e.g. AWS Bedrock SigV4, Vertex AI OAuth2).
///
/// The returned reference points into the static registry — no allocation.
pub fn complex_provider_names() -> Result<Vec<String>, String> {
    liter_llm::provider::complex_provider_names()
        .map(|v| v.iter().map(|s| s.to_string()).collect::<Vec<_>>())
        .map_err(|e| e.to_string())
}

/// Calculate the estimated cost of a completion given a model name and token
/// counts.
///
/// Returns `null` if the model is not present in the embedded pricing registry.
/// Returns `Some(cost_usd)` otherwise, where the value is in US dollars.
///
/// When an exact model name match is not found, progressively shorter prefixes
/// are tried by stripping from the last `-` or `.` separator. For example,
/// `gpt-4-0613` will match `gpt-4` if no `gpt-4-0613` entry exists.
pub fn completion_cost(model: String, prompt_tokens: i64, completion_tokens: i64) -> Option<f64> {
    liter_llm::completion_cost(&model, prompt_tokens as u64, completion_tokens as u64)
}

/// Calculate the estimated cost of a completion, accounting for cached
/// (cache-hit) prompt tokens billed at the provider's discounted rate.
///
/// `cached_tokens` is the count of prompt tokens served from the provider's
/// prompt cache. It must be `<= prompt_tokens` (cached tokens are a subset of
/// the prompt). The non-cached portion is billed at `input_cost_per_token`
/// and the cached portion at `cache_read_input_token_cost` when the model
/// has cache pricing; otherwise the entire prompt is billed at the regular
/// input rate.
///
/// Returns `null` if the model is not present in the embedded pricing
/// registry, mirroring `completion_cost`.
///
/// When the model has `ModelPricing.tiers`, the tier whose
/// `min_context_tokens` is the highest value `<= prompt_tokens` supplies the
/// input/output/cache rates for the whole call; models without tiers (or
/// when `prompt_tokens` is below every tier threshold) use the base rates
/// unchanged, matching the original flat-rate behaviour.
pub fn completion_cost_with_cache(
    model: String,
    prompt_tokens: i64,
    cached_tokens: i64,
    completion_tokens: i64,
) -> Option<f64> {
    liter_llm::completion_cost_with_cache(
        &model,
        prompt_tokens as u64,
        cached_tokens as u64,
        completion_tokens as u64,
    )
}

/// Calculate completion cost including both prompt-cache reads and writes.
pub fn completion_cost_with_cache_details(
    model: String,
    prompt_tokens: i64,
    cached_tokens: i64,
    cache_creation_tokens: i64,
    completion_tokens: i64,
) -> Option<f64> {
    liter_llm::completion_cost_with_cache_details(
        &model,
        prompt_tokens as u64,
        cached_tokens as u64,
        cache_creation_tokens as u64,
        completion_tokens as u64,
    )
}

/// Look up FFI-friendly pricing and capability metadata for a model.
///
/// Returns `null` if the model is not present in the active pricing
/// registry. Uses the same exact-match-then-prefix-fallback resolution as
/// `model_pricing`; unlike `model_pricing`, the result is an owned
/// `ModelInfo` value safe to hand across the FFI boundary.
///
/// When a runtime catalog refresh has succeeded, this reflects the refreshed
/// (overlay) catalog; otherwise it reflects the embedded catalog. See
/// `model_pricing` for the embedded-only alternative.
pub fn model_info(model: String) -> Option<ModelInfo> {
    liter_llm::model_info(&model).map(ModelInfo::from)
}

/// Look up model metadata only when the requested catalog key exists exactly.
pub fn exact_model_info(model: String) -> Option<ModelInfo> {
    liter_llm::exact_model_info(&model).map(ModelInfo::from)
}

/// Return provenance for the active runtime or embedded model catalog.
pub fn catalog_info() -> Option<CatalogInfo> {
    liter_llm::catalog_info().map(CatalogInfo::from)
}

/// Install the overlay registry from a raw catalog JSON string, bypassing
/// the network and disk cache entirely.
///
/// Parses and flattens `catalog_json` with the same
/// `registry_from_catalog_str` logic used for the embedded catalog and the
/// network refresh path, then atomically swaps it in as the active overlay.
/// A parse failure returns `CatalogRefreshError.Parse` and leaves any
/// existing overlay untouched.
///
/// This is primarily a testable seam: it lets tests exercise overlay
/// installation and the embedded/overlay fallback behavior in
/// `completion_cost` / `model_info` without a real network
/// call.
pub fn install_catalog_overlay_from_str(catalog_json: String) -> Result<(), String> {
    liter_llm::install_catalog_overlay_from_str(&catalog_json)
        .map(|v| v)
        .map_err(|e| e.to_string())
}

/// Clear the overlay registry, reverting `completion_cost`,
/// `completion_cost_with_cache`, and `model_info` to the
/// embedded catalog.
///
/// Primarily a test seam (see `install_catalog_overlay_from_str`); also
/// usable by long-running processes that want to abandon a runtime refresh.
pub fn clear_catalog_overlay() {
    liter_llm::clear_catalog_overlay();
}

/// Refresh the runtime catalog overlay per `config`.
///
/// - `config.enabled == false`: returns `Ok(RefreshOutcome.Disabled)`
///   immediately. No network, filesystem, or overlay activity.
///
/// - A fresh on-disk cache (age < `config.ttl_seconds`) exists at the
///   resolved cache path (`config.cache_path`, or a default under
///   `std.env.temp_dir()`): read + flatten it and install the overlay,
///   returning `Ok(RefreshOutcome.FromCache)`. No network request is
///   made.
///
/// - Otherwise: validate `config.source_url` uses `https`
///   (`CatalogRefreshError.InsecureUrl` otherwise), fetch it, flatten it,
///   install the overlay, best-effort write the raw JSON to the cache path
///   (a cache write failure does not fail the refresh), and return
///   `Ok(RefreshOutcome.Fetched)`.
///
/// On any error return, the overlay is left untouched: the previously
/// active registry (a prior successful overlay, or the embedded catalog if
/// none was ever installed) remains in effect. This is what makes the
/// feature air-gap-safe — an unreachable or invalid `source_url` never
/// degrades `completion_cost` / `model_info` below embedded-catalog
/// availability.
pub async fn refresh_catalog(config: CatalogRefreshConfig) -> Result<RefreshOutcome, String> {
    let item = &config;
    u64::try_from(item.ttl_seconds)
        .map_err(|_| "CatalogRefreshConfig.ttl_seconds is outside the valid u64 range".to_string())?;
    liter_llm::refresh_catalog(&liter_llm::CatalogRefreshConfig::from(config))
        .await
        .map(RefreshOutcome::from)
        .map_err(|e| e.to_string())
}

/// Remove all guardrails from the global registry.
///
/// Primarily useful in tests to reset state between test cases.
///
/// If the lock was poisoned by a panicking guardrail on a previous access,
/// the poisoned state is recovered rather than propagating the panic.
pub fn clear() {
    liter_llm::guardrail::registry::clear();
}

/// Count tokens in a text string using the tokenizer for the given model.
///
/// The tokenizer is resolved from the model name prefix (e.g. `"gpt-4o"` maps
/// to the `Xenova/gpt-4o` HuggingFace tokenizer). Tokenizers are cached after
/// first load.
///
/// **Errors:**
///
/// Returns `LiterLlmError.BadRequest` if the tokenizer cannot be loaded
/// (e.g. network failure on first use) or if tokenization itself fails.
#[cfg(feature = "tokenizer")]
pub fn count_tokens(model: String, text: String) -> Result<i64, String> {
    liter_llm::count_tokens(&model, &text)
        .map(|v| v as i64)
        .map_err(|e| e.to_string())
}

/// Count tokens for a full `ChatCompletionRequest`.
///
/// Sums tokens across all message text contents plus a per-message overhead
/// of ~4 tokens (for role, separators, and formatting metadata). Tool
/// definitions and multimodal content parts (images, audio, documents) are
/// not counted — only textual content contributes to the token total.
///
/// **Errors:**
///
/// Returns `LiterLlmError.BadRequest` if the tokenizer cannot be loaded or
/// if tokenization fails for any message.
#[cfg(feature = "tokenizer")]
pub fn count_request_tokens(model: String, req: ChatCompletionRequest) -> Result<i64, String> {
    let item = &req;
    if let Some(value) = item.n {
        u32::try_from(value).map_err(|_| "ChatCompletionRequest.n is outside the valid u32 range".to_string())?;
    }
    if let Some(value) = item.max_tokens {
        u64::try_from(value)
            .map_err(|_| "ChatCompletionRequest.max_tokens is outside the valid u64 range".to_string())?;
    }
    if let Some(value) = item.top_logprobs {
        u32::try_from(value)
            .map_err(|_| "ChatCompletionRequest.top_logprobs is outside the valid u32 range".to_string())?;
    }
    if let Some(value) = item.max_completion_tokens {
        u64::try_from(value)
            .map_err(|_| "ChatCompletionRequest.max_completion_tokens is outside the valid u64 range".to_string())?;
    }
    liter_llm::count_request_tokens(&model, &liter_llm::types::ChatCompletionRequest::from(req))
        .map(|v| v as i64)
        .map_err(|e| e.to_string())
}

/// Record the estimated USD cost of a completion.
///
/// Call from `CostTrackingService` once a
/// completion's cost has been computed. Emits `gen_ai.client.cost.usd`.
/// If the meter has not been initialized, this call is a no-op.
#[cfg(feature = "tower")]
pub fn record_cost_usd(system: String, model: String, operation: String, cost_usd: f64) {
    liter_llm::tower::metrics::record_cost_usd(&system, &model, &operation, cost_usd);
}

/// Assert that `current_len + incoming` does not exceed `limit`.
///
/// Call this before appending `incoming` bytes to any buffer that must
/// stay below `limit`. Returns `Err(LiterLlmError.Streaming)` on overflow
/// and emits a `tracing.warn!` with context.
pub fn check_bound(context: String, current_len: i64, incoming: i64, limit: i64) -> Result<(), String> {
    liter_llm::util::bounds::check_bound(
        &context,
        usize::try_from(current_len)
            .map_err(|_| "parameter 'current_len' must be between 0 and usize::MAX".to_string())?,
        usize::try_from(incoming).map_err(|_| "parameter 'incoming' must be between 0 and usize::MAX".to_string())?,
        usize::try_from(limit).map_err(|_| "parameter 'limit' must be between 0 and usize::MAX".to_string())?,
    )
    .map(|v| v)
    .map_err(|e| e.to_string())
}

/// Install the `ring` crypto provider as the rustls process default, idempotently.
///
/// rustls 0.23+ removed the implicit default provider. This function installs
/// `ring` once per process. Subsequent calls are no-ops. Calling it after
/// another rustls crypto provider has already been installed is safe: the
/// `Err` from `install_default()` is silently ignored.
///
/// Called automatically by every internal `reqwest.Client` constructor
/// (auth providers, default HTTP client). Bindings and downstream consumers
/// reach those constructors transitively, so no manual init is required.
///
/// WASM builds are exempt — the WASM target uses the browser/Node.js fetch
/// API instead of rustls, so no crypto provider is needed.
///
/// Windows builds use native-tls (SChannel) via reqwest, so rustls is not
/// present and no crypto provider installation is needed.
#[cfg(any(
    all(any(feature = "native-http", feature = "opendal-cache"), not(target_os = "windows")),
    all(any(feature = "native-http", feature = "opendal-cache"), target_os = "windows")
))]
pub fn ensure_crypto_provider() {
    liter_llm::ensure_crypto_provider();
}

